import BenchmarkTools
using Printf
using SpecialFunctions: acsch

# Float32 version (matches stdlib acschf semantics):
acschf(x::Float32) = Float32( acsch( Float64(x) ) )

# Benchmark variables:
name = "acschf";
repeats = 3;

"""
	print_version()

Prints the TAP version.
"""
function print_version()
	@printf( "TAP version 13\n" );
end

"""
	print_summary( total, passing )

Print the benchmark summary.
"""
function print_summary( total, passing )
	@printf( "#\n" );
	@printf( "1..%d\n", total );
	@printf( "# total %d\n", total );
	@printf( "# pass  %d\n", passing );
	@printf( "#\n" );
	@printf( "# ok\n" );
end

"""
	print_results( iterations, elapsed )

Print benchmark results.
"""
function print_results( iterations, elapsed )
	rate = iterations / elapsed

	@printf( "  ---\n" );
	@printf( "  iterations: %d\n", iterations );
	@printf( "  elapsed: %0.9f\n", elapsed );
	@printf( "  rate: %0.9f\n", rate );
	@printf( "  ...\n" );
end

"""
	benchmark()

Run a benchmark.
"""
function benchmark()
	t = BenchmarkTools.@benchmark acschf(
		Float32( (200.0*rand()) - 100.0 )
	) samples=1e6

	# Total elapsed time (seconds):
	s = sum( t.times ) / 1.0e9;

	# Number of iterations:
	iter = length( t.times );

	[ iter, s ];
end

"""
	main()

Run benchmarks.
"""
function main()
	print_version();
	for i in 1:repeats
		@printf( "# julia::%s\n", name );
		results = benchmark();
		print_results( results[1], results[2] );
		@printf( "ok %d benchmark finished\n", i );
	end
	print_summary( repeats, repeats );
end

main();
